28: const SAVE_KEY = 'gol-legends-save-v1';
29: const freshState = () => ({coins:1250,inventory:[],squad:[],packs:0,claimed:[],trainingUsed:false});
30: let state;
31: try { state = {...freshState(), ...JSON.parse(localStorage.getItem(SAVE_KEY) || '{}')}; } catch { state = freshState(); }
32: state.inventory = Array.isArray(state.inventory) ? state.inventory : [];
33: state.squad = Array.isArray(state.squad) ? state.squad : [];
34: state.claimed = Array.isArray(state.claimed) ? state.claimed : [];
35: let activeFilter = 'all';
36: let pendingCards = [];
37: let toastTimer;
38: const $ = (s, root=document) => root.querySelector(s);
39: const $$ = (s, root=document) => [...root.querySelectorAll(s)];
40: const fmt = n => Number(n).toLocaleString('ru-RU');
41: function save(){localStorage.setItem(SAVE_KEY,JSON.stringify(state));renderAll();}
42: function player(id){return PLAYERS.find(p=>p.id===id);}
43: function ownedCount(id){return state.inventory.filter(c=>c.id===id).length;}
44: function uniqueCount(){return new Set(state.inventory.map(c=>c.id)).size;}
45: function notify(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2500);}
46: function cardMarkup(p, extraClass='', instance=''){
47:  const rarity = p.kind === 'legend' ? 'card-legend' : p.kind === 'star' ? 'card-rare' : 'card-common';
48:  const kit = p.dark || '#203a2e';
49:  return `<article class="player-card ${rarity} ${extraClass}" style="--kit:${p.color};--kit-dark:${kit}" data-id="${p.id}" ${instance ? `data-instance="${instance}"` : ''} aria-label="${p.name}, ${p.rating} баллов">
50:   <div class="pc-tag">${p.kind==='legend'?'ЛЕГЕНДА':p.kind==='star'?'ЗВЕЗДА':'ЗОЛОТО'}</div><div class="pc-top"><span class="pc-rating">${p.rating}</span><span class="pc-pos">${p.pos}</span></div>
51:   <div class="player-art"><div class="player-silhouette"><i class="head"></i><i class="hair"></i><i class="body"></i><span class="number">${p.country==='АРГ'?'10':p.country==='ПОР'?'7':p.country==='БРА'?'11':'9'}</span></div></div>
52:   <div class="pc-name">${p.short}</div><div class="pc-club">${p.club} · ${p.country}</div><div class="pc-footer"><span>СКОРОСТЬ</span><strong>${p.stats[0]}</strong><span>УДАР</span><strong>${p.stats[1]}</strong></div></article>`;
53: }
54: function renderAll(){
55:  $('#coinBalance').textContent=fmt(state.coins);
56:  $('#squadCount').textContent=state.squad.length;
57:  const avg=state.squad.length?Math.round(state.squad.reduce((sum,id)=>sum+(player(id)?.rating||0),0)/state.squad.length):null;
58:  $('#teamRating').textContent=avg||'—'; $('#squadRating').textContent=avg||'—';
59:  $('#collectionTotal').textContent=String(state.inventory.length).padStart(2,'0');
60:  $('#filterAll').textContent=state.inventory.length;
61:  const progress=Math.min(uniqueCount()/10*100,100);$('#sideProgress').style.width=`${progress}%`;
62:  updateMissionSummary(); renderRecent(); renderCollection(); renderSquad(); renderChallenges();
63: }
64: function missionProgress(){return {open:state.packs>0?1:0,collect:Math.min(uniqueCount(),5),squad:Math.min(state.squad.length,5)};}
65: function updateMissionSummary(){
66:  const m=missionProgress();$('#missionOpenProgress').style.width=`${m.open*100}%`;$('#missionCollectProgress').style.width=`${m.collect/5*100}%`;
67:  const openDone=m.open>=1;const collectDone=m.collect>=5;
68:  $('#missionOpenCheck').textContent=openDone?'✓':'○';$('#missionCollectCheck').textContent=collectDone?'✓':'○';
69:  $('#missionOpenCheck').classList.toggle('completed',openDone);$('#missionCollectCheck').classList.toggle('completed',collectDone);
70: }
71: function renderRecent(){
72:  const host=$('#recentList');if(!state.inventory.length){host.innerHTML='<div class="empty-state"><span>✦</span><p>Пока пусто. Твоя первая звезда уже ждёт.</p></div>';return;}
73:  host.innerHTML=state.inventory.slice(-6).reverse().map(c=>{const p=player(c.id);return `<div class="recent-player" style="--accent:${p.color}"><span class="recent-rating">${p.rating}</span><div><strong>${p.name}</strong><small>${p.club}</small></div><span class="recent-tag">${p.kind==='legend'?'ЛЕГЕНДА':p.kind==='star'?'ЗВЕЗДА':'ЗОЛОТО'}</span></div>`;}).join('');
74: }
75: function renderCollection(){
76:  const host=$('#collectionGrid');const filtered=state.inventory.filter(c=>{const p=player(c.id);return activeFilter==='all'||p.kind===activeFilter;});
77:  if(!filtered.length){host.innerHTML=`<div class="no-cards"><b>${state.inventory.length?'В ЭТОЙ КАТЕГОРИИ ПОКА ПУСТО':'КОЛЛЕКЦИЯ ЖДЁТ ПЕРВУЮ ЗВЕЗДУ'}</b><span>Открой пак на главной, чтобы найти футболистов.</span></div>`;return;}
78:  host.innerHTML=filtered.slice().reverse().map(c=>cardMarkup(player(c.id),'',c.uid)).join('');
79: }
80: function renderSquad(){
81:  const slots=$('#pitchSlots');slots.innerHTML=Array.from({length:5},(_,i)=>{const id=state.squad[i];if(!id)return `<div class="pitch-slot"><div class="pitch-placeholder">+</div><span>ПОЗИЦИЯ ${String(i+1).padStart(2,'0')}</span></div>`;const p=player(id);return `<div class="pitch-slot"><div class="pitch-card" style="--accent:${p.color}"><span class="recent-rating">${p.rating}</span><div><strong>${p.short}</strong><small>${p.pos} · ${p.country}</small></div></div><button data-remove="${id}">УБРАТЬ ×</button></div>`;}).join('');
82:  $('#squadPoolCount').textContent=`${state.inventory.length} В КОЛЛЕКЦИИ`;
83:  const owned=[...new Set(state.inventory.map(c=>c.id))];const pool=$('#squadPool');
84:  if(!owned.length){pool.innerHTML='<div class="empty-pool">Сначала открой пак, чтобы найти игроков.</div>';return;}
85:  pool.innerHTML=owned.map(id=>{const p=player(id);const selected=state.squad.includes(id);return `<button class="pool-player" data-add="${id}" ${selected||state.squad.length>=5?'disabled':''} style="--accent:${p.color}"><span class="recent-rating">${p.rating}</span><span><strong>${p.short}</strong><small>${p.pos} · ${p.club}</small></span><span class="pool-add">${selected?'✓':'+'}</span></button>`;}).join('');
86: }
87: const CHALLENGES=[{id:'first-pack',icon:'▤',title:'Первый шаг',desc:'Открой свой первый футбольный пак',reward:100,progress:()=>Math.min(state.packs,1),goal:1},{id:'five-players',icon:'♙',title:'Коллекционер',desc:'Собери 5 разных футболистов',reward:150,progress:()=>Math.min(uniqueCount(),5),goal:5},{id:'full-squad',icon:'⚽',title:'Тренер мечты',desc:'Добавь 5 игроков в свой состав',reward:200,progress:()=>Math.min(state.squad.length,5),goal:5}];
88: function renderChallenges(){
89:  const host=$('#challengeList');let done=0;
90:  host.innerHTML=CHALLENGES.map(c=>{const progress=c.progress();const claimed=state.claimed.includes(c.id);if(claimed)done++;return `<article class="challenge-item"><div class="challenge-icon">${c.icon}</div><div class="challenge-info"><span>ЗАДАНИЕ · НАГРАДА ◉ ${c.reward}</span><strong>${c.title}</strong><small>${c.desc} · ${progress}/${c.goal}</small><div class="mission-track"><i style="width:${progress/c.goal*100}%"></i></div></div><div class="challenge-reward">◉ +${c.reward}<br><button class="claim-btn" data-claim="${c.id}" ${progress<c.goal||claimed?'disabled':''}>${claimed?'ПОЛУЧЕНО':progress>=c.goal?'ЗАБРАТЬ':'В ПРОЦЕССЕ'}</button></div></article>`;}).join('');
91:  $('#challengeDone').textContent=`${done}/3`;
92: }
93: function generatePack(){
94:  const available=PLAYERS.filter(p=>true);const weights=available.map(p=>p.kind==='legend'?4:p.kind==='star'?24:72);
95:  return Array.from({length:3},()=>{let n=Math.random()*weights.reduce((a,b)=>a+b,0);let chosen=available[0];for(let i=0;i<available.length;i++){n-=weights[i];if(n<=0){chosen=available[i];break;}}return chosen;});
96: }
97: function startPack(){
98:  if(pendingCards.length){notify('Сначала забери все карточки из текущего пака.');return;}
99:  if(state.coins<250){notify('Не хватает монет. Выполни задание или забери тренировочную награду!');return;}
100:  state.coins-=250;state.packs++;save();
101:  const stage=$('#packStage'),wrap=$('#packWrap'),cards=$('#revealCards');
102:  $('#openPack').disabled=true;$('#tapHint').classList.remove('show');$('#packCaption').textContent='ТВОЯ ФУТБОЛЬНАЯ ИСТОРИЯ...';
